select plan_year, size_segment, units_plan, units_basis,
       revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select count(distinct org_id) as clients_2024
from read_parquet('data/payments.parquet')
where date_part('year', paid_at) = 2024
  and recorded_at <= date '2025-10-01';

-- план по сегментам, сумма по всем метрикам плана
select plan_year, size_segment, units_plan,
       revenue_plan_model, revenue_plan_premium,
       revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select size_segment, units_plan,
       revenue_plan_model, revenue_plan_approved
from read_parquet('data/plan.parquet')
where plan_year = 2024
order by size_segment;

select count(distinct org_id) as clients_2024
from read_parquet('data/payments.parquet')
where paid_at >= date '2024-01-01'
  and paid_at < date '2025-01-01'
  and recorded_at <= date '2025-10-01';

select plan_year, size_segment, units_plan, units_basis,
       revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select distinct plan_year, size_segment, revision_date
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select size_segment,
       revenue_plan_model, revenue_plan_premium,
       revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
where plan_year = 2021
order by size_segment;

select
  plan_year,
  sum(revenue_plan_approved) as plan_total
from read_parquet('data/plan.parquet')
group by plan_year
order by plan_year;

select distinct plan_year, size_segment, units_plan, units_basis
from read_parquet('data/plan.parquet')
order by 1,2;

-- 2. Факт revenue за 2024 (cash, по paid_at, с курсором по recorded_at)
select
  round(sum(amount),2) as revenue_cash_2024
from read_parquet('data/payments.parquet')
where paid_at >= '2024-01-01' and paid_at <= '2024-12-31'
  and recorded_at <= '2025-10-01';

-- 3. Факт client_count (orgs, active) за 2024
select
  count(distinct org_id) as clients_active_2024
from read_parquet('data/payments.parquet')
where paid_at >= '2024-01-01' and paid_at <= '2024-12-31'
  and recorded_at <= '2025-10-01';

select planned_renewal_month, count(*) as n_subs
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select date_trunc('month', start_date) as start_month, count(*) as n
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select date_trunc('month', end_date) as end_month, count(*) as n
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select extract(year from start_date) as yr, count(*) as n_new_subs
from read_parquet('data/subscriptions.parquet')
group by 1 order by 1;

select extract(year from registered_at) as yr, count(*) as n_new_orgs
from read_parquet('data/orgs.parquet')
group by 1 order by 1;

select date_trunc('month', period_end) as month,
       count(*) as n_periods
from read_parquet('data/invoices.parquet')
where period_end >= '2025-01-01' and period_end < '2025-10-01'
group by 1 order by 1;

-- План на 2024 по сегментам
select size_segment, units_plan, units_basis,
       revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
where plan_year = 2024
order by size_segment;

select plan_year, size_segment, units_plan, units_basis,
       revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment;

select count(distinct org_id) as client_count_2024
from read_parquet('data/payments.parquet')
where paid_at >= '2024-01-01' and paid_at < '2025-01-01'
  and recorded_at <= '2025-10-01';

select plan_year, size_segment, units_plan, revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment

select size_segment, count(*) 
from read_parquet('data/orgs.parquet')
group by size_segment

select
  planned_renewal_month,
  count(*) as subs_planned
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select
  date_trunc('month', start_date) as start_month,
  count(*) as subs_started
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

select
  planned_renewal_month,
  count(*) as n_subs
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

-- сколько подписок (звеньев цепочки) у организации
select max_seq, count(*) as n_orgs
from (
  select org_id, max(seq_no) as max_seq
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t
group by max_seq
order by max_seq

-- 1. "Наивный" LT: просто средняя длительность по полю duration_months (все подписки, включая продлённые цепочки)
select avg(duration_months)/12.0 as lt_years_naive_field
from read_parquet('data/subscriptions.parquet');
